# Precisamos exatamente de 10 provas. As listas foram construídas para totalizar 10.
assert len(provas) == 10, len(provas)
assert all(len(p) == 20 for p in provas)

for i, questoes in enumerate(provas, 1):
    lines = [f"PROVA: Assistente de Tecnologia — Prova {i}", ""]
    for n, (q, alts, gab) in enumerate(questoes, 1):
        lines.append(f"{n}) {q}")
        lines.extend(alts)
        lines.append(f"GABARITO: {gab}")
        lines.append("")
    (base / f"prova_{i:02d}.txt").write_text("\n".join(lines), encoding="utf-8")

# Criar também um ZIP com os 10 arquivos
import zipfile
zip_path = Path("/mnt/data/provas_assistente_tecnologia_10_arquivos.zip")
with zipfile.ZipFile(zip_path, "w", zipfile.ZIP_DEFLATED) as z:
    for f in sorted(base.glob("prova_*.txt")):
        z.write(f, arcname=f.name)

print(f"Arquivos criados: {len(list(base.glob('*.txt')))}")
print(f"ZIP: {zip_path}")
for f in sorted(base.glob("*.txt")):
    print(f.name, f.stat().st_size, "bytes")
